const { execSync } = require('child_process');

const repoUrl = $input.first().json.body?.repoUrl || $input.first().json.repoUrl;
if (!repoUrl) throw new Error('No repoUrl provided in request body');

try {
  const cmd = `mkdir -p /tmp/web-audit-platform && cd /tmp/web-audit-platform && rm -rf repo && git clone --depth 1 ${repoUrl} repo 2>&1`;
  execSync(cmd, { encoding: 'utf-8', timeout: 60000 });
  return [{ json: { repoUrl } }];
} catch (error) {
  throw new Error(`Failed to clone repository: ${error.message}. Make sure this is a public Git repo URL (e.g. https://github.com/user/repo).`);
}

const { execSync } = require('child_process');

let vulnerabilities = 0;
let auditData = {};
let auditError = null;

try {
  const cmd = `find /tmp/web-audit-platform/repo -name "package.json" -not -path "*/node_modules/*" -exec dirname {} \\;`;
  const dirs = execSync(cmd, { encoding: 'utf-8' }).split('\n').filter(Boolean);

  if (dirs.length === 0) {
    auditError = 'No package.json found in repository';
  }

  for (const dir of dirs) {
    try {
      execSync(`cd "${dir}" && npm install --package-lock-only 2>&1`, { timeout: 120000 });
      execSync(`cd "${dir}" && npm audit --json 2>&1`, { encoding: 'utf-8' });
    } catch (err) {
      if (err.stdout) {
        try {
          const parsed = JSON.parse(err.stdout);
          vulnerabilities += (parsed.metadata?.vulnerabilities?.critical || 0) + (parsed.metadata?.vulnerabilities?.high || 0);
          auditData = parsed;
        } catch (e) {
          auditError = 'Could not parse npm audit output';
        }
      }
    }
  }
} catch (error) {
  auditError = error.message;
}

const repoUrl = $input.first().json.repoUrl;
return [{ json: { repoUrl, auditOutput: auditData, critical_vulnerabilities: vulnerabilities, auditError } }];

const { execSync } = require('child_process');

let complexityErrors = 0;
let eslintData = [];
let eslintError = null;

try {
  const pythonCmd = (() => { try { execSync('python3 --version 2>&1'); return 'python3'; } catch(e) { try { execSync('python --version 2>&1'); return 'python'; } catch(e2) { return null; } } })();
  if (!pythonCmd) throw new Error('Python not available in this environment');
  execSync(`${pythonCmd} -m pip install lizard --quiet 2>&1`, { timeout: 60000 });
  const cmd = `${pythonCmd} -m lizard /tmp/web-audit-platform/repo --csv -C 10 2>&1 || true`;
  const output = execSync(cmd, { encoding: 'utf-8', timeout: 60000 });
  const lines = output.trim().split('\n').filter(Boolean);
  for (const line of lines) {
    const parts = line.split(',');
    if (parts.length >= 8) {
      const ccn = parseInt(parts[2]);
      if (!isNaN(ccn) && ccn > 10) {
        complexityErrors++;
        eslintData.push({
          filePath: parts[0]?.trim().split('/repo/').pop(),
          functionName: parts[7]?.trim(),
          complexity: ccn,
          line: parts[5]?.trim()
        });
      }
    }
  }
} catch (error) {
  eslintError = error.message;
}

const prev = $input.first().json;
return [{
  json: {
    repoUrl: prev.repoUrl,
    scannedAt: new Date().toISOString(),
    critical_vulnerabilities: prev.critical_vulnerabilities,
    auditOutput: prev.auditOutput,
    auditError: prev.auditError || null,
    complexityErrors,
    eslintData,
    eslintError: eslintError || null
  }
}];

const d = $input.first().json;

const vulnList = d.auditOutput?.vulnerabilities
  ? Object.values(d.auditOutput.vulnerabilities).filter(v => v.severity === 'high' || v.severity === 'critical').map(v => `- ${v.name} (${v.severity}): ${Array.isArray(v.via) ? v.via.filter(x => typeof x === 'object').map(x => x.title).join(', ') : ''}`).join('\n')
  : 'None found';

const complexList = d.eslintData?.slice(0, 20).map(f => `- ${f.filePath} | ${f.functionName} | complexity: ${f.complexity}`).join('\n') || 'None found';

const prompt = `You are a senior software engineer reviewing an automated repository audit. Give concrete, actionable suggestions.

Repository: ${d.repoUrl}
Scanned: ${d.scannedAt}

## Dependency Vulnerabilities (High/Critical): ${d.critical_vulnerabilities}
${vulnList}

## Cyclomatic Complexity Violations (threshold >10): ${d.complexityErrors}
${complexList}

Provide:
1. A brief overall assessment (2-3 sentences)
2. Top 3 priority fixes with specific steps
3. Any patterns you notice across the codebase`;

return [{ json: { ...d, geminiPrompt: prompt } }];

const scanData = $node['Build Gemini Prompt'].json;
const geminiResponse = $input.first().json;

const suggestions = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text || 'No suggestions available';

return [{ json: { ...scanData, aiSuggestions: suggestions } }];

const d = $input.first().json;
return [{ json: {
  scannedAt: d.scannedAt,
  repoUrl: d.repoUrl,
  critical_vulnerabilities: d.critical_vulnerabilities,
  complexityErrors: d.complexityErrors,
  auditError: d.auditError || '',
  eslintError: d.eslintError || ''
} }];

const d = $input.first().json;
return [{ json: {
  scannedAt: d.scannedAt,
  repoUrl: d.repoUrl,
  fullReport: JSON.stringify({
    critical_vulnerabilities: d.critical_vulnerabilities,
    auditOutput: d.auditOutput,
    complexityErrors: d.complexityErrors,
    eslintData: d.eslintData,
    auditError: d.auditError,
    eslintError: d.eslintError,
    aiSuggestions: d.aiSuggestions
  })
} }];
